#!/usr/bin/env python3
"""Local factual repair of the four original independent English essays, not retranslation."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];M=R/'data/childhood/multilingual';source=json.loads((M/'source-original.json').read_text())['articles'];changes={}
def replace(e,n,old,new,why):
 before=source[e-1]['body_en'][n-1];text=changes.get((e,n),{}).get('after',before);assert old in text,(e,n,old)
 c=changes.setdefault((e,n),dict(article=e,source_block=n,before=before,after=text,reasons=[]));c['after']=text.replace(old,new);c['reasons'].append(why)
def put(e,n,new,why):replace(e,n,source[e-1]['body_en'][n-1],new,why)
put(1,1,'Alyosha first sees the Kashirin household after a boat reaches Nizhny Novgorod. His father has just died. His younger brother was born before the father’s burial; on the subsequent journey from Astrakhan, the baby dies and is buried at Saratov. Alyosha is still very young, arriving inside grief he cannot yet interpret.','ChapterI: birth before voyage, death during it; no false precise age.')
replace(1,19,'Now seventeen or eighteen','Now nineteen','ChapterIII explicitly nineteen.')
put(1,20,'During Alyosha’s beating, Tsyganok slips his arm beneath the switches to absorb some of the blows. Later he shows the child his injured arm and explains: he hoped a switch would break, giving Mother or Grandmother time to carry Alyosha away while Grandfather fetched another. He felt sorry for the child.','ChapterII explicit motive, plan and shown injuries; not an inexplicable secret act.')
put(1,22,'Shielding Alyosha brings Tsyganok pain. He does not demand anything from the child in exchange. He is a foundling and worker protecting the owner’s grandson, a child he scarcely knows. Showing the injuries afterward does not turn the protection into a bargain.','No false secrecy or impossibility of praise; retain unreciprocated protection.')
put(1,24,'The distinction is not between an act with a reason and one without one. Tsyganok gives a reason: pity for a child being beaten. Nor must help remain unknown to retain its character. The gesture gives Alyosha evidence that a human being can answer another’s pain without first asking what the answer will return.','Replace directly dependent false-secrecy argument, preserving nonexchange thesis rather than inventing a different one.')
put(2,11,'He turns survival into evidence for the injuries that accompanied it, including what a person survived despite rather than because of it. Yet he has heard a counterexample: Alyosha’s mother tells him that the boy’s father never beat the child and forbade her to do so, believing that blows could not teach him well. Hearing this does not displace Grandfather’s faith in his own experience.','ChapterII mother gives explicit counterexample; not absence of any comparison.')
put(2,13,'Grandfather does more than strike. He teaches Alyosha from a new book with energy and pleasure, praising quick progress but also shouting until the child joins in. He tells stories—of the Volga, of French prisoners brought to Balakhna after 1812, of people encountered across a hard life—and becomes animated while telling them.','ChapterV new book, lively shouting not pure patience; prisoners not invasion of his home.')
put(2,19,'The household breaks apart and its property changes hands. The sons separate and continue badly. In old age Grandfather and Grandmother count even their ordinary expenses separately: they can use the same teapot yet measure out their individual shares of tea. She works and makes lace; he still possesses money and lends it at interest, including seven hundred rubles from selling her belongings. He also solicits money from acquaintances and merchants by pleading poverty. The book does not narrate his death: he is still there to send Alyosha out to earn a living.','ChapterXIII retained capital and lending, shared teapot, grandfather alive at ending.')
put(2,20,'His lifelong economy does not preserve the household’s closeness. Sons hate him; his daughter once fled his authority; Yakov beat his own wife to death. The old couple increasingly divides daily life into separate charges. Money remains in Grandfather’s hands, but the habits that carried him from the river to ownership cannot make family attachment secure.','Do not invent total destitution or no living ties; distinguish concrete perpetrator from household critique.')
replace(2,22,'an old primer','a new primer','ChapterV book is new.')
put(3,4,'His prayers use fixed phrases of confession, mercy and the removal of sinful desires. He stands straight and speaks loudly. In the religion he describes to the child, God watches severely and may punish; worldly gains and losses also acquire religious explanations. In this punitive order, prayer begins to resemble an account book.','ChapterVII actual prayers not invented itemized enemy list; distinguish interpretation from wording.')
put(3,5,'Grandfather requires Alyosha to learn prayers. At the beginning, it is Aunt Natalya who teaches him and, when he asks about words he does not understand, tells him not to ask but to repeat them. Correct repetition matters more than meaning. Religion joins discipline as another field in which authority confirms itself.','ChapterII command by grandfather, instruction and refusal of explanation by aunt.')
put(3,7,'Alyosha is a child making a comparison. Grandmother does criticize her husband and even jokes that he repeats the same prayers without a word from the heart. But she does not hand Alyosha a finished theory of the two practices. Grandfather certainly offers no such comparison. The child carries out that judgment himself.','Criticism exists; independent judgment is not absence of received examples or exact age seven-eight.')
put(3,10,'Grandmother’s God is involved in how a person lives and feels closer and more merciful to the child. This is not a God wholly without punishment: she also tells of angels reporting a child’s mischief and God ordering Grandfather to chastise him. Yet her prayer repeatedly returns to daily concerns. She asks protection even for the man who harms her, admits her own failures, and returns to the day’s tasks.','ChapterIV grandmother also describes divine punishment; preserve experienced contrast rather than absolute no-ledger claim.')
put(3,19,'Grandmother is beaten throughout her marriage. In one scene Grandfather punches her head and kicks her after she falls; hairpins are driven into her scalp, and Alyosha helps remove them. She asks him not to tell his mother because mother and grandfather already resent one another. She also curses the old man. Her tendency to excuse him does not mean she never protests; readers can still ask how such endurance allows violence to continue.','ChapterX fists/kicks drive existing hairpins into scalp; no handheld needle or certified broken fragments; specific concealment reason and criticism retained.')
put(3,22,'When the dye works catches fire, the household panics. Grandmother runs into the burning building to retrieve a container of sulfuric acid before it brings further danger. The horse blanket over her shoulders catches fire; she calls for it to be removed, and Grigory pulls it off. She directs people, horses, and water. Her hands are burned, and that night she says they hurt.','ChapterIV sulfuric acid, burning horse blanket, awareness and expressed pain; courage does not require insensibility.')
put(3,25,'Tsyganok, the foundling Grandmother raised, carries the heaviest end of an oak cross intended for the grave of Yakov’s wife—the wife he had beaten to death. According to Yakov’s account afterward, Tsyganok slips, the two uncles release their end, and the cross crushes him. Alyosha has not gone with them. They bring Tsyganok home, and he bleeds to death on the kitchen floor.','ChapterIII child is not eyewitness to accident; account comes home with Yakov.')
put(3,26,'Accusations are part of the scene. Grigory blames the uncles for killing him; Grandfather calls them wolves and says he knows Tsyganok stood in their way. The accusations are explicit; the question of deliberate intent remains unresolved. Grandfather is angry and grieves, while also thinking of the fine craftsman lost. Grandmother returns, kneels, touches and arranges the young man, then tells the others to leave.','Do not erase accusations or convert them into proven murder; do not invent grandmother holding him throughout his dying.')
replace(3,32,'a non-accounting God','a God who feels closer and more merciful','Avoid absolute absence of punishment while retaining child’s contrast.')
put(4,7,'Alyosha tells him stories. Good Thing listens, notices when he invents things, and points out unnecessary words. Having heard Grandmother’s stories, he urges the child to learn to write and set them down. He takes the child’s telling seriously: words should answer to what is actually observed, rather than merely fill the air.','ChapterVIII verified advice rather than invented verbatim sequence-instruction; retain accuracy argument.')
replace(4,10,'Alyosha remembers him','The adult narrator remembers him','Make retrospective framing explicit; no child predicting a future life.')
replace(4,16,'an eleven- or twelve-year-old','a child of about ten or eleven','Avoid unsupported exact age; preserve early working-child context.')
put(4,17,'The narrator closes Childhood by saying that he went out into the world. The next volume, often rendered In the World or My Apprenticeship, opens with him already serving in a shoe shop. The ending leads directly into that next life. Childhood ends not with education completed but with the withdrawal of household support.','Different actual ending/opening; retain thematic transition.')
replace(4,19,'a God who does not keep accounts','a God experienced as closer and more merciful','Grandmother’s divine world includes punishment; no absolute erasure.')
replace(4,29,'the secret protection of a child','the protection of a child without a demand for repayment','Protection revealed to child, not secrecy-based moral proof.')
arts=[];titles=['The Dye Works','Grandfather and the Towrope','Two Gods','He Went Out into the World'];decks=['A household’s accounts, a beating, a story, and an arm offered in protection.','What the rope taught, what the switch repeats, and what neither cancels.','A child distinguishes two ways of seeing people within one household.','Conflicting gifts, an adult’s recollection, and the child sent out to work.']
for i,a in enumerate(source):
 body=[changes.get((i+1,j+1),{}).get('after',x) for j,x in enumerate(a['body_en'])];assert len(body)==len(a['body_en']);assert [j for j,x in enumerate(body) if x.startswith('## ')]==[j for j,x in enumerate(a['body_en']) if x.startswith('## ')]
 arts.append({'slug':a['slug'],'title':titles[i],'deck':decks[i],'body':body,'source_note':body[-1],'edition_note':'The original independently structured English essay, retained with documented local factual corrections. It is not a block-by-block retranslation of the Chinese. Full-book spoilers.','coverage':f'Retained independent English: {len(body)} original and current blocks. Local factual and dependent-argument changes are recorded separately.'})
(M/'en.json').write_text(json.dumps({'language':'en','series':{'title':'Reading Childhood','deck':'Four essays on household accounts, inherited violence, unreciprocated care and the beginnings of judgment.','intro':[],'note':'Maxim Gorky, Childhood (1913–1914). The original English essays retain their independent structures with local corrections.'},'ui':{'series':'Reading Childhood'},'articles':arts},ensure_ascii=False,indent=2)+'\n')
(M.parent/'english-corrections.json').write_text(json.dumps({'method':'Retain original four independent essays and their 29/30/33/33-block structures. Repair specific facts and directly dependent claims; do not force Chinese-English equality or retranslate all material.','corrections':list(changes.values())},ensure_ascii=False,indent=2)+'\n');print('Retained 125 English blocks; local changes in',len(changes),'blocks.')
